SELECT
       ccu.usuario_id AS usuarioId,
       ccu.expansion_id AS expansionId,
       ccu.carta_juego_id AS cartaJuegoId,
       c.nombre,
       c.rareza_id AS rarezaId,
       c.energia_id AS energiaId,
       c.tipo_id AS tipoId,
       ccu.obtenida
FROM carta_usuario ccu
JOIN carta c
  ON ccu.expansion_id = c.expansion_id
 AND ccu.carta_juego_id = c.carta_juego_id


        AND ccu.usuario_id = #{usuarioId}


        AND ccu.carta_juego_id = #{cartaJuegoId}


        AND c.nombre LIKE CONCAT('%', #{nombre}, '%')


        AND c.rareza_id IN

            #{rarezaId}



        AND c.expansion_id IN

            #{expansionId}



        AND c.energia_id IN

            #{energiaId}



        AND c.tipo_id IN

            #{tipoId}



        AND ccu.obtenida = #{obtenida}


ORDER BY ccu.expansion_id ASC, ccu.carta_juego_id ASC;

